#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Map 2 manual setup for clanka-bot. Run on the Pi, from the repo root (where
# .env and docker-compose.yml live). Values land in .env only: CI needs none of
# them, so no GitHub Actions secrets are written. Every token entry is hidden.

# Reads one field from `tailscale status --json` without needing jq.
_ts_field() {
  command -v tailscale >/dev/null 2>&1 && command -v python3 >/dev/null 2>&1 || return 0
  tailscale status --json 2>/dev/null | python3 -I -c '
import json, sys
s = json.load(sys.stdin); me = s.get("Self", {})
if sys.argv[1] == "login":
    print(s.get("User", {}).get(str(me.get("UserID")), {}).get("LoginName", ""))
else:
    print(me.get("DNSName", "").rstrip("."))' "$1" 2>/dev/null || true
}

run_wizard() {

TOTAL_STAGES=10

banner "clanka-bot Map 2 setup"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "Preflight: right machine, right folder"
say "Run this on the deploy host, in a clean clanka-bot checkout on integration/map-2:"
note "  scripts/map-2-setup-wizard.sh   (from the repo root)"
if [[ ! -f docker-compose.yml || ! -f .env.example ]]; then
  warn "No docker-compose.yml/.env.example here. cd to the repo root and re-run."
  exit 1
fi
BRANCH=$(git rev-parse --abbrev-ref HEAD 2>/dev/null || echo unknown)
note "branch: $BRANCH @ $(git rev-parse --short HEAD 2>/dev/null || echo ?)"
# make deploy pulls and builds the CURRENT branch and refuses a dirty tree, so
# catch both here instead of at stage 9.
if [[ "$BRANCH" != "integration/map-2" ]]; then
  warn "This checkout is on '$BRANCH', not integration/map-2: stage 9 would deploy the wrong code."
  note "Use a clean Map 2 checkout, e.g.: git worktree add ../clanka-bot-deploy integration/map-2"
  confirm "Continue anyway?" || exit 1
fi
if [[ -n "$(git status --porcelain --untracked-files=normal 2>/dev/null)" ]]; then
  warn "The working tree has local changes; 'make deploy' refuses to run on it (stage 9)."
  note "Use a clean checkout for deploys, or commit/stash first."
  confirm "Continue anyway?" || exit 1
fi
if [[ ! -f "$ENV_FILE" ]]; then
  if confirm "No $ENV_FILE yet. Copy .env.example to $ENV_FILE (mode 600)?"; then
    (umask 077 && cp .env.example "$ENV_FILE"); say "created $ENV_FILE"
  else
    warn "write_env will create a bare $ENV_FILE instead."
  fi
fi
command -v tailscale >/dev/null 2>&1 || warn "tailscale not found: install it first (docs/deploy.md, Pi base setup)."
command -v docker    >/dev/null 2>&1 || warn "docker not found: install it first (docs/deploy.md)."
pause "Press Enter to continue"

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Dashboard owner and host (Tailscale identity)"
say "The Dashboard only answers your Tailscale login, on the Pi's exact ts.net name."
TS_LOGIN=$(_ts_field login); TS_HOST=$(_ts_field host)
[[ -n "$TS_LOGIN" ]] && note "detected login: $TS_LOGIN"
[[ -n "$TS_HOST"  ]] && note "detected host:  $TS_HOST"
note "If nothing was detected, run 'tailscale status --json' and read Self.DNSName and your User LoginName."
ask ASSISTANT_DASHBOARD_OWNER "Your Tailscale login (e.g. you@github or an email)${TS_LOGIN:+ [detected: $TS_LOGIN]}:"
[[ -z "$ASSISTANT_DASHBOARD_OWNER" ]] && ASSISTANT_DASHBOARD_OWNER="$TS_LOGIN"
ask ASSISTANT_DASHBOARD_HOSTS "The Pi's MagicDNS name, no https:// (e.g. pi.tail1234.ts.net)${TS_HOST:+ [detected: $TS_HOST]}:"
[[ -z "$ASSISTANT_DASHBOARD_HOSTS" ]] && ASSISTANT_DASHBOARD_HOSTS="$TS_HOST"
write_env ASSISTANT_DASHBOARD_PORT "8082"
write_env ASSISTANT_DASHBOARD_OWNER "$ASSISTANT_DASHBOARD_OWNER"
write_env ASSISTANT_DASHBOARD_HOSTS "$ASSISTANT_DASHBOARD_HOSTS"
PI_HOST="${ASSISTANT_DASHBOARD_HOSTS%%,*}"
pause "Press Enter to continue"

# ── 3 ────────────────────────────────────────────────────────────────────
stage "Tailnet HTTPS and tailscale serve"
say "tailscale serve needs MagicDNS and HTTPS certificates on for the tailnet."
open_url "https://login.tailscale.com/admin/dns"
step "On the DNS page: make sure MagicDNS is enabled."
step "Scroll to 'HTTPS Certificates' and click Enable HTTPS (skip if already on)."
pause "Press Enter once both are on"
if confirm "Publish the loopback Dashboard to the tailnet now (tailscale serve --bg 8082)?"; then
  tailscale serve --bg 8082 || sudo tailscale serve --bg 8082 \
    || SKIPPED+=("tailscale serve --bg 8082 (failed; run it by hand)")
  tailscale serve status || true
else
  SKIPPED+=("tailscale serve --bg 8082")
fi
warn "Never use 'tailscale funnel' or a LAN port mapping for 8082."
pause "Press Enter to continue"

# ── 4 ────────────────────────────────────────────────────────────────────
stage "GitHub: fine-grained token (issues + PRs)"
say "Used by github.issue_create and github.pr_list for Jairik/clanka-bot only."
open_url "https://github.com/settings/personal-access-tokens/new"
step "Token name: clanka-bot assistant. Pick an expiry you're happy to rotate."
step "Resource owner: Jairik. Repository access: Only select repositories → clanka-bot."
step "Repository permissions: Issues → Read and write; Pull requests → Read-only."
step "Leave everything else at No access. Generate token, then copy it (shown once)."
ask_secret GITHUB_TOKEN "Paste the fine-grained token (github_pat_…), or Enter to skip:"
if [[ -n "$GITHUB_TOKEN" ]]; then write_env GITHUB_TOKEN "$GITHUB_TOKEN"
else SKIPPED+=("GITHUB_TOKEN (fine-grained PAT)"); fi
pause "Press Enter to continue"

# ── 5 ────────────────────────────────────────────────────────────────────
stage "GitHub: classic token, notifications only (optional)"
say "GitHub's notifications API rejects fine-grained tokens, so this one is separate."
open_url "https://github.com/settings/tokens/new?scopes=notifications&description=clanka-bot%20notifications"
step "Check ONLY the 'notifications' box (the link pre-ticks it). Untick anything else."
step "Set an expiry, Generate token, copy it (ghp_…)."
ask_secret GITHUB_NOTIFICATIONS_TOKEN "Paste the classic token, or Enter to skip:"
if [[ -n "$GITHUB_NOTIFICATIONS_TOKEN" ]]; then write_env GITHUB_NOTIFICATIONS_TOKEN "$GITHUB_NOTIFICATIONS_TOKEN"
else note "Skipped: 'what are my GitHub notifications' will say a classic token is needed."; fi
pause "Press Enter to continue"

# ── 6 ────────────────────────────────────────────────────────────────────
stage "ntfy: phone notifications"
say "A random topic acts as the address; anyone who knows it can read it, so keep it private."
NTFY_TOPIC=$(_existing NTFY_TOPIC || true)
if [[ -z "$NTFY_TOPIC" ]]; then
  NTFY_TOPIC="clanka-$(od -An -N12 -tx1 /dev/urandom | tr -d ' \n')"
fi
write_env NTFY_TOPIC "$NTFY_TOPIC"
printf '\n  %sTopic:%s %s\n\n' "$BOLD" "$RESET" "$NTFY_TOPIC"
step "Install the ntfy app on your phone (Play Store / App Store / F-Droid)."
step "Tap + (Subscribe to topic), enter the topic above, keep server ntfy.sh, Subscribe."
step "Android: allow ntfy notifications and exclude it from battery optimisation."
note "Leave NTFY_TOKEN empty for ntfy.sh. Set it only if you self-host and ran 'ntfy token add'."
note "If the assistant already generated its own topic, paste this one on Dashboard /secrets too (stored value wins)."
pause "Press Enter once the phone is subscribed"

# ── 7 ────────────────────────────────────────────────────────────────────
stage "Spotify: developer app (Web API, PKCE)"
SPOTIFY_REDIRECT_URI="https://${PI_HOST}/spotify/callback"
say "Needs Spotify Premium. No client secret is used."
open_url "https://developer.spotify.com/dashboard"
step "Log in, click Create app. Name: Clanka. Description: home assistant."
step "Redirect URI, exactly (click Add):"
printf '\n      %s%s%s\n\n' "$BOLD" "$SPOTIFY_REDIRECT_URI" "$RESET"
step "Under 'Which API/SDKs are you planning to use?' tick Web API. Accept terms, Save."
step "Open the app's Settings (Basic Information) and copy the Client ID."
step "User Management tab: add your own Spotify account email (development mode)."
ask SPOTIFY_CLIENT_ID "Paste the Client ID (public, 32 hex chars):"
write_env SPOTIFY_CLIENT_ID "$SPOTIFY_CLIENT_ID"
write_env SPOTIFY_REDIRECT_URI "$SPOTIFY_REDIRECT_URI"
DEFAULT_IF=$(ip route show default 2>/dev/null | awk '{for(i=1;i<=NF;i++) if($i=="dev"){print $(i+1); exit}}')
note "Connect discovery uses mDNS on the LAN interface. Default route: ${DEFAULT_IF:-unknown}."
ask SPOTIFY_ZEROCONF_INTERFACE "LAN interface name (eth0/wlan0), or Enter for auto-detect:"
write_env SPOTIFY_ZEROCONF_INTERFACE "$SPOTIFY_ZEROCONF_INTERFACE"
pause "Press Enter to continue"

# ── 8 ────────────────────────────────────────────────────────────────────
stage "OpenRouter: Agent path key"
say "Without it, anything the Fast path can't route answers 'unavailable'."
say "If it's already in .env, just press Enter to keep it."
open_url "https://openrouter.ai/settings/keys"
step "Create key (name: clanka-bot), optionally set a credit limit, copy it (sk-or-…)."
ask_secret OPENROUTER_API_KEY "Paste the OpenRouter key, or Enter to keep/skip:"
if [[ -n "$OPENROUTER_API_KEY" ]]; then write_env OPENROUTER_API_KEY "$OPENROUTER_API_KEY"
else SKIPPED+=("OPENROUTER_API_KEY (Agent path stays off)"); fi
pause "Press Enter to continue"

# ── 9 ────────────────────────────────────────────────────────────────────
stage "Deploy and smoke-test the Dashboard"
if confirm "Run 'make deploy' now (pull, build, restart, wait for health)?"; then
  make deploy || warn "make deploy failed: read the 'deploy:' lines above (dirty tree, pull, build or health)."
  printf '\n'
  code=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:8082/health || echo 000)
  say "loopback, no identity header → $code (expect NOT 200)"
  code=$(curl -s -o /dev/null -w '%{http_code}' -H "Tailscale-User-Login: $ASSISTANT_DASHBOARD_OWNER" http://127.0.0.1:8082/health || echo 000)
  say "loopback, owner header       → $code (expect 200)"
else
  SKIPPED+=("make deploy + Dashboard curl checks (runbook §1)")
fi
pause "Press Enter to continue"

# ── 10 ───────────────────────────────────────────────────────────────────
stage "Spotify: Connect pairing and Web API sign-in"
say "Do this from your phone or laptop on the tailnet (and the same LAN for Connect)."
open_url "https://${PI_HOST}/spotify"
step "On the /spotify page, click Connect and approve the Spotify consent screen."
step "Back on /secrets, check SPOTIFY_REFRESH_TOKEN is listed (name only)."
step "Phone Spotify app → Connect icon → pick '$(_existing SPOTIFY_DEVICE_NAME || echo Clanka)' → play a track."
step "Sound should come from the Pi. /health should show librespot and Web API as separate OK rows."
note "Ducking and the music Tools only turn on once the Web API sign-in is done."
pause "Press Enter when done"

finish
say "Next: work through docs/runbooks/map-2-acceptance.md §1–§8 and paste results into each issue."
say "Optional #76: run 'opencode auth login' to store a fresh OpenCode Go key (never paste it anywhere)."
printf '\n'
}

run_wizard "$@"; exit
